import { chromium } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import fs from 'node:fs/promises';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';

const base = 'http://127.0.0.1:1431/';
const out = 'docs/rebuild/receipts';
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 800, height: 600 }, colorScheme: 'dark', locale: 'en-US' });
const page = await context.newPage();
const events = { pageErrors: [], failedRequests: [] };
page.on('pageerror', (e) => events.pageErrors.push(e.message));
page.on('requestfailed', (r) => events.failedRequests.push({ url: r.url(), failure: r.failure()?.errorText }));
const hash = (data) => crypto.createHash('sha256').update(data).digest('hex');
const result = { schemaVersion: 1, command: 'node .omnia-ui-qa-final-temp.mjs', result: 'passed_with_findings', asOf: new Date().toISOString(), revision: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(), base, environment: { kind: 'vite-browser-preview', viewport: { width: 800, height: 600 }, packaged: false, native: false, provider: false }, screens: [], keyboard: {}, events, captures: [], sourceFiles: [], findings: [], limitations: ['Fresh disposable Chromium context; no mock/live provider or native Tauri APIs injected.', 'Preview captures and axe checks do not prove packaged Windows UIA/WebView2/native behavior.', 'No live provider, project pointer storage, RAG, OS automation, downloads, or plugin mutation tested.', 'UI controls existing only below the fold or behind dialog overlays are distinguished from exposed hit targets; a matching document size alone does not prove control accessibility.'] };
const sources = ['src/main.tsx','src/rebuild/rebuild-app.tsx','src/rebuild/rebuild-app.css','src/rebuild/chat/chat-view.tsx','src/rebuild/chat/chat-view.css','src/rebuild/settings/SettingsPanel.tsx','src/rebuild/settings/settings.css','src/rebuild/settings/settings.ts','src/rebuild/browser/browser-workspace.tsx','src/rebuild/ide/ide-workspace.tsx'];
for (const path of sources) { const data = await fs.readFile(path); result.sourceFiles.push({ path, sha256: hash(data) }); }
const inspect = () => page.evaluate(() => {
  const controls = [...document.querySelectorAll('button,input,textarea,select,[role=button],[role=tab],[role=menuitem]')].map((e) => {
    const r = e.getBoundingClientRect(); const s = getComputedStyle(e); const shown = r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none'; const x = r.x + r.width / 2; const y = r.y + r.height / 2; const top = shown && x >= 0 && x < innerWidth && y >= 0 && y < innerHeight ? document.elementFromPoint(x, y) : null;
    const labels = e.labels ? [...e.labels].map((l) => l.textContent).join(' ') : '';
    return { tag: e.tagName.toLowerCase(), role: e.getAttribute('role'), name: (e.getAttribute('aria-label') || labels || e.getAttribute('title') || e.textContent || '').replace(/\s+/g,' ').trim().slice(0,150), disabled: e.hasAttribute('disabled') || e.getAttribute('aria-disabled') === 'true', shown, centerExposed: Boolean(top && (top === e || e.contains(top))), rect: { x: r.x, y: r.y, width: r.width, height: r.height, right: r.right, bottom: r.bottom } };
  });
  const companion = document.querySelector('.rb-companion-chat'); const cr = companion?.getBoundingClientRect();
  return { surface: document.querySelector('.rb-app')?.getAttribute('data-surface'), theme: document.documentElement.dataset.rebuildTheme, scroll: { body: { width: document.body.scrollWidth, height: document.body.scrollHeight }, html: { width: document.documentElement.scrollWidth, height: document.documentElement.scrollHeight } }, controls, companion: { present: Boolean(companion), displayed: Boolean(cr && cr.width > 0 && cr.height > 0), display: companion ? getComputedStyle(companion).display : null }, composerVisible: [...document.querySelectorAll('[aria-label="Message composer"]')].some((e) => { const r=e.getBoundingClientRect(); return r.width > 0 && r.height > 0; }) };
});
const focus = () => page.evaluate(() => {
  const e = document.activeElement; const r = e?.getBoundingClientRect(); const s = e ? getComputedStyle(e) : null;
  return { tag: e?.tagName?.toLowerCase(), name: (e?.getAttribute?.('aria-label') || e?.getAttribute?.('title') || e?.textContent || '').replace(/\s+/g,' ').trim().slice(0,150), insideSettings: Boolean(e?.closest?.('.settings-panel')), visible: Boolean(r && r.width > 0 && r.height > 0), outlineStyle: s?.outlineStyle, outlineWidth: s?.outlineWidth, rect: r ? { x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom } : null };
});
const audit = async (name) => {
  await page.waitForTimeout(150);
  const snapshot = await inspect();
  const axe = await new AxeBuilder({ page }).withTags(['wcag2a','wcag2aa','wcag21a','wcag21aa']).analyze();
  const path = `${out}/ui-qa-${name}.png`;
  await page.screenshot({ path, fullPage: true, animations: 'disabled' });
  result.captures.push({ path, sha256: hash(await fs.readFile(path)), viewport: { width: 800, height: 600 }, kind: 'browser-preview' });
  const screen = { name, ...snapshot, ariaSnapshot: await page.locator('body').ariaSnapshot(), axe: { violations: axe.violations.map((v) => ({ id:v.id,impact:v.impact,help:v.help,nodes:v.nodes.map((n)=>({target:n.target,summary:n.failureSummary})) })), passes: axe.passes.length, incomplete: axe.incomplete.length } };
  result.screens.push(screen);
  return screen;
};
try {
  await page.emulateMedia({ reducedMotion:'reduce' });
  await page.goto(base, { waitUntil:'networkidle' });
  await page.getByRole('navigation', { name:'Primary surfaces' }).waitFor();
  await audit('800x600-dark');
  const mainFocus=[]; for(let i=0;i<45;i+=1){await page.keyboard.press('Tab');mainFocus.push(await focus());} result.keyboard.mainFocus=mainFocus;
  await page.getByRole('button',{name:'Toggle theme'}).click();
  await page.waitForFunction(()=>document.documentElement.dataset.rebuildTheme==='light');
  await audit('800x600-light');
  await page.getByRole('button',{name:'Browser',exact:true}).click();
  await audit('800x600-browser-light');
  await page.keyboard.press('Alt+3');
  await page.waitForFunction(()=>document.querySelector('.rb-app')?.getAttribute('data-surface')==='ide');
  await audit('800x600-ide-light');
  result.keyboard.alt3ChangedToIde=true;
  await page.keyboard.press('Alt+1');
  await page.waitForFunction(()=>document.querySelector('.rb-app')?.getAttribute('data-surface')==='chat');
  result.keyboard.alt1ChangedToChat=true;
  await page.getByRole('button',{name:'Open settings'}).click();
  await page.getByRole('dialog',{name:'Advanced runtime'}).waitFor();
  result.keyboard.focusOnSettingsOpen=await focus();
  await audit('800x600-settings-light');
  const settingsFocus=[]; for(let i=0;i<45;i+=1){await page.keyboard.press('Tab');settingsFocus.push(await focus());} result.keyboard.settingsFocus=settingsFocus;
  await page.keyboard.press('Escape');
  result.keyboard.settingsRemainsAfterEscape=await page.getByRole('dialog',{name:'Advanced runtime'}).isVisible();
  await page.getByRole('button',{name:'Close settings'}).click();
  result.keyboard.focusAfterSettingsClose=await focus();
  await page.reload({waitUntil:'networkidle'});
  result.themeAfterReload=await page.evaluate(()=>document.documentElement.dataset.rebuildTheme);
  result.themeReloadPersisted=result.themeAfterReload==='light';
  for (const s of result.screens) if (s.scroll.html.width>800 || s.scroll.html.height>600) result.findings.push({id:'document-overflow',screen:s.name,detail:s.scroll});
  for (const s of result.screens.filter((s)=>['browser','ide'].includes(s.surface))) if(!s.composerVisible) result.findings.push({id:'companion-chat-hidden-at-800',screen:s.name,detail:'Companion chat exists in DOM but is display:none at <=1100px; no composer is accessible in this surface.'});
  if(result.keyboard.settingsFocus.some((f)=>!f.insideSettings)) result.findings.push({id:'settings-focus-escapes',detail:'Tab traversal reaches controls outside aria-modal dialog.'});
  if(!result.keyboard.focusOnSettingsOpen.insideSettings) result.findings.push({id:'settings-focus-not-moved',detail:'Opening Settings does not move focus into dialog.'});
  if(result.keyboard.settingsRemainsAfterEscape) result.findings.push({id:'settings-escape-does-not-close',detail:'Escape leaves Settings open.'});
  const settingsScreen=result.screens.find((s)=>s.name==='800x600-settings-light');
  if(settingsScreen?.controls.filter((c)=>c.role==='tab').some((c)=>!c.centerExposed)) result.findings.push({id:'settings-tabs-obscured',detail:'All Settings section tabs have nonzero layout boxes but their hit-test centers are obscured by the body; the screenshot confirms no section tab labels are visible.',tabs:settingsScreen.controls.filter((c)=>c.role==='tab').map((c)=>({name:c.name,centerExposed:c.centerExposed,rect:c.rect}))});
  for(const s of result.screens) for(const v of s.axe.violations) result.findings.push({id:`axe-${v.id}`,screen:s.name,impact:v.impact,nodes:v.nodes.length});
  result.exitCode=0;
} catch(e) { result.result='failed';result.exitCode=1;result.error=String(e?.stack||e);process.exitCode=1; }
finally {
  result.completedAt=new Date().toISOString();
  result.scriptSource=await fs.readFile('.omnia-ui-qa-final-temp.mjs','utf8');
  result.scriptSha256=hash(result.scriptSource);
  const body=JSON.stringify(result,null,2)+'\n';
  await fs.writeFile(`${out}/ui-qa-narrow-accessibility-20261108.json`,body);
  await fs.writeFile(`${out}/ui-qa-narrow-accessibility-20261108.sha256`,`${hash(body)}  ui-qa-narrow-accessibility-20261108.json\n`);
  console.log(JSON.stringify({result:result.result,findings:result.findings,screenSummary:result.screens.map((s)=>({name:s.name,controls:s.controls.length,axeViolations:s.axe.violations.length,composerVisible:s.composerVisible,scroll:s.scroll})),themeReloadPersisted:result.themeReloadPersisted,events:result.events,sha256:hash(body)},null,2));
  await context.close();await browser.close();
}
